package com.chaosmod;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("stream-events")
public interface ChaosModConfig extends Config
{
	String GROUP = "stream-events";

	@ConfigItem(keyName = "autoStart", name = "Enable random events", description = "Enable random events after a countdown")
	default boolean autoStart() { return false; }

	@ConfigItem(keyName = "showSidebarPanel", name = "Show sidebar panel", description = "Show the Chaos Mod event tester in RuneLite's sidebar")
	default boolean showSidebarPanel() { return false; }

	@Range(min = 0, max = 120)
	@ConfigItem(keyName = "betweenRoundsSeconds", name = "Time until next event", description = "Seconds to wait before the next random event")
	default int betweenRoundsSeconds() { return 60; }

	@Range(min = 5, max = 180)
	@ConfigItem(keyName = "eventSeconds", name = "Default event duration", description = "Used unless that event has its own duration below")
	default int eventSeconds() { return 30; }

	@ConfigItem(keyName = "showEventTileIndicators", name = "Show event tile indicators", description = "Show optional danger and target tiles for events")
	default boolean showEventTileIndicators() { return true; }

	@ConfigSection(name = "Event duration overrides", description = "Set an event to 0 to use the default event duration", closedByDefault = true, position = 10)
	String eventDurationOverrides = "eventDurationOverrides";

	@Range(min = 0, max = 180) @ConfigItem(keyName = "barrelsSeconds", name = "Exploding Barrels", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int barrelsSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "lightsOutSeconds", name = "Lights Out", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int lightsOutSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "jadSeconds", name = "Spawn Jad", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int jadSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "meteorSeconds", name = "Yama Meteor Shower", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int meteorSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "noobOutfitSeconds", name = "Noob Outfit", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int noobOutfitSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "guitarHeroSeconds", name = "Guitar Hero", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int guitarHeroSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "vardorvisSeconds", name = "Vardorvis Captcha", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int vardorvisSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "dirtyScreenSeconds", name = "Dirty Screen", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int dirtyScreenSeconds() { return 0; }
	@Range(min = 0, max = 180) @ConfigItem(keyName = "coxPortalsSeconds", name = "CoX Portals", description = "0 uses Default event duration", section = eventDurationOverrides)
	default int coxPortalsSeconds() { return 0; }

	@ConfigSection(name = "Random event pool", description = "Choose which events can be selected by the random timer", closedByDefault = true, position = 20)
	String randomEventPool = "randomEventPool";

	@ConfigItem(keyName = "includeBarrels", name = "Exploding Barrels", description = "Include Exploding Barrels in random events", section = randomEventPool)
	default boolean includeBarrels() { return true; }
	@ConfigItem(keyName = "includeLightsOut", name = "Lights Out", description = "Include Lights Out in random events", section = randomEventPool)
	default boolean includeLightsOut() { return true; }
	@ConfigItem(keyName = "includeJad", name = "Spawn Jad", description = "Include Spawn Jad in random events", section = randomEventPool)
	default boolean includeJad() { return true; }
	@ConfigItem(keyName = "includeMeteor", name = "Yama Meteor Shower", description = "Include Yama Meteor Shower in random events", section = randomEventPool)
	default boolean includeMeteor() { return true; }
	@ConfigItem(keyName = "includeNoobOutfit", name = "Noob Outfit", description = "Include Noob Outfit in random events", section = randomEventPool)
	default boolean includeNoobOutfit() { return true; }
	@ConfigItem(keyName = "includeGuitarHero", name = "Guitar Hero", description = "Include Guitar Hero in random events", section = randomEventPool)
	default boolean includeGuitarHero() { return true; }
	@ConfigItem(keyName = "includeVardorvis", name = "Vardorvis Captcha", description = "Include Vardorvis Captcha in random events", section = randomEventPool)
	default boolean includeVardorvis() { return true; }
	@ConfigItem(keyName = "includeDirtyScreen", name = "Dirty Screen", description = "Include Dirty Screen in random events", section = randomEventPool)
	default boolean includeDirtyScreen() { return true; }
	@ConfigItem(keyName = "includeCoxPortals", name = "CoX Portals", description = "Include CoX Portals in random events", section = randomEventPool)
	default boolean includeCoxPortals() { return true; }

}

package com.chaosmod;

import com.chaosmod.events.ChaosMod;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** Draws event effects over the 3D scene but underneath all game widgets. */
final class ChaosModEffectOverlay extends Overlay
{
	private final Client client;
	private final ChaosModPlugin plugin;
	private final ChaosModConfig config;

	@Inject
	ChaosModEffectOverlay(Client client, ChaosModPlugin plugin, ChaosModConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.HIGH);
	}

	@Override public Dimension render(Graphics2D graphics)
	{
		ChaosMod activeEvent = plugin.getActiveEvent();
		if (activeEvent != null)
		{
			activeEvent.render(client, graphics);
			if (config.showEventTileIndicators())
			{
				activeEvent.renderTileMarkers(client, graphics);
			}
		}
		return null;
	}
}

package com.chaosmod;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;

import com.chaosmod.events.ChaosMod;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class ChaosModOverlay extends Overlay
{
	private static final Color COUNTDOWN_TITLE_COLOR = new Color(0x55D9FF);
	private static final Color ACTIVE_TITLE_COLOR = new Color(0xFFB347);
	private final ChaosModPlugin plugin;
	private final PanelComponent panel = new PanelComponent();

	@Inject
	ChaosModOverlay(ChaosModPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
		panel.setPreferredSize(new Dimension(310, 0));
	}

	@Override public Dimension render(Graphics2D graphics)
	{
		panel.getChildren().clear();
		long seconds = Math.max(0, Duration.between(Instant.now(), plugin.getDeadline()).getSeconds() + 1);
		if (plugin.getPhase() == ChaosModPlugin.Phase.ACTIVE && plugin.getActiveEvent() != null)
		{
			ChaosMod activeEvent = plugin.getActiveEvent();
			panel.getChildren().add(TitleComponent.builder().text("EVENT ACTIVE  •  " + seconds + "s").color(ACTIVE_TITLE_COLOR).build());
			panel.getChildren().add(LineComponent.builder().left(activeEvent.getName()).build());
			panel.getChildren().add(LineComponent.builder().left(activeEvent.getDescription()).leftColor(Color.LIGHT_GRAY).build());
		}
		else
		{
			panel.getChildren().add(TitleComponent.builder().text("NEXT RANDOM EVENT  •  " + seconds + "s").color(COUNTDOWN_TITLE_COLOR).build());
		}
		return panel.render(graphics);
	}
}

package com.chaosmod;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** Sidebar controls for manually testing every registered stream event. */
final class ChaosModPanel extends PluginPanel
{
	private static final int GAP = 6;

	private final ChaosModPlugin plugin;
	private final JPanel eventButtons = new JPanel();

	@Inject
	ChaosModPanel(ChaosModPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Chaos Mod Event Tester", SwingConstants.CENTER);
		title.setForeground(ColorScheme.TEXT_COLOR);
		title.setAlignmentX(Component.CENTER_ALIGNMENT);
		title.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		content.add(title);
		content.add(Box.createVerticalStrut(GAP));

		JLabel help = new JLabel("<html><center>Start any event immediately.<br>"
			+ "The current countdown or event will stop.</center></html>", SwingConstants.CENTER);
		help.setForeground(ColorScheme.TEXT_COLOR);
		help.setAlignmentX(Component.CENTER_ALIGNMENT);
		help.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		content.add(help);
		content.add(Box.createVerticalStrut(10));

		eventButtons.setLayout(new BoxLayout(eventButtons, BoxLayout.Y_AXIS));
		eventButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(eventButtons);
		content.add(Box.createVerticalStrut(12));

		JButton stopButton = createButton("Stop active event");
		stopButton.addActionListener(event -> plugin.stopTestEvent());
		content.add(stopButton);

		add(content, BorderLayout.NORTH);
	}

	void rebuildEventButtons()
	{
		eventButtons.removeAll();
		List<String> eventNames = plugin.getAvailableEventNames();
		for (String eventName : eventNames)
		{
			JButton button = createButton(eventName);
			button.addActionListener(event -> plugin.startTestEvent(eventName));
			eventButtons.add(button);
			eventButtons.add(Box.createVerticalStrut(GAP));
		}
		eventButtons.revalidate();
		eventButtons.repaint();
	}

	private static JButton createButton(String text)
	{
		JButton button = new JButton(text);
		button.setAlignmentX(Component.CENTER_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		button.setFocusable(false);
		return button;
	}
}

package com.chaosmod;

import com.google.inject.Provides;
import com.chaosmod.events.ChaosMod;
import com.chaosmod.events.ChaosModFactory;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import javax.imageio.ImageIO;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(name = "Chaos Mod", description = "Random client-side events for livestreams",
	tags = {"stream", "events", "random"}, internalName = "chaos-mod")
public class ChaosModPlugin extends Plugin
{
	enum Phase { WAITING, ACTIVE }

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private ChaosModConfig config;
	@Inject private ConfigManager configManager;
	@Inject private OverlayManager overlayManager;
	@Inject private ChaosModOverlay overlay;
	@Inject private ChaosModEffectOverlay eventEffectOverlay;
	@Inject private ChaosModWidgetOverlay eventWidgetOverlay;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ChaosModPanel panel;
	@Inject private ScheduledExecutorService executor;

	private final Random random = new Random();
	@Getter private Phase phase = Phase.WAITING;
	@Getter private Instant deadline = Instant.EPOCH;
	@Getter private ChaosMod activeEvent;
	private ScheduledFuture<?> transitionTask;
	private NavigationButton navigationButton;

	@Override protected void startUp()
	{
		// Make sure autostart is always off when runelite starts so people dont instantly die lol
		configManager.setConfiguration(ChaosModConfig.GROUP, "autoStart", false);
		overlayManager.add(overlay);
		overlayManager.add(eventEffectOverlay);
		overlayManager.add(eventWidgetOverlay);
		panel.rebuildEventButtons();
		updateSidebarPanel();
		if (config.autoStart()) scheduleNewRound(config.betweenRoundsSeconds());
		log.info("Chaos Mod started");
	}

	@Override protected void shutDown()
	{
		cancelTransition();
		overlayManager.remove(overlay);
		overlayManager.remove(eventEffectOverlay);
		overlayManager.remove(eventWidgetOverlay);
		removeSidebarPanel();
		ChaosMod eventToStop = activeEvent;
		activeEvent = null;
		phase = Phase.WAITING;
		deadline = Instant.EPOCH;
		if (eventToStop != null)
		{
			clientThread.invokeLater(() -> eventToStop.stop(client));
		}
		log.info("Chaos Mod stopped");
	}

	@Subscribe public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && phase == Phase.WAITING && config.autoStart()) scheduleNewRound(config.betweenRoundsSeconds());
	}

	@Subscribe public void onConfigChanged(ConfigChanged event)
	{
		if (!ChaosModConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("showSidebarPanel".equals(event.getKey()))
		{
			updateSidebarPanel();
			return;
		}
		if (!"autoStart".equals(event.getKey()))
		{
			return;
		}

		if (!config.autoStart())
		{
			if (phase == Phase.WAITING)
			{
				cancelTransition();
				deadline = Instant.EPOCH;
			}
			return;
		}

		if (phase == Phase.WAITING)
		{
			scheduleNewRound(config.betweenRoundsSeconds());
		}
	}

	@Subscribe public void onGameTick(GameTick tick)
	{
		if (activeEvent != null)
		{
			activeEvent.onGameTick(client);
			if (activeEvent != null && activeEvent.isComplete())
			{
				finishEvent();
			}
		}
	}

	@Subscribe public void onClientTick(ClientTick tick)
	{
		if (activeEvent != null) activeEvent.onClientTick(client);
	}

	@Subscribe public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (activeEvent != null) activeEvent.onMenuOptionClicked(client, event);
	}

	@Subscribe public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (activeEvent != null) activeEvent.onScriptCallbackEvent(client, event);
	}

	void startRound() { clientThread.invoke(this::startRandomEvent); }

	List<String> getAvailableEventNames()
	{
		List<String> names = new ArrayList<>();
		for (ChaosMod event : ChaosModFactory.createAllEvents(random, config))
		{
			names.add(event.getName());
		}
		return names;
	}

	void startTestEvent(String eventName)
	{
		clientThread.invoke(() ->
		{
			ChaosMod selected = null;
			for (ChaosMod event : ChaosModFactory.createAllEvents(random, config))
			{
				if (event.getName().equals(eventName))
				{
					selected = event;
					break;
				}
			}

			if (selected == null)
			{
				return;
			}

			cancelTransition();
			if (activeEvent != null)
			{
				activeEvent.stop(client);
			}
			activeEvent = selected;
			phase = Phase.ACTIVE;
			deadline = Instant.now().plusSeconds(activeEvent.getDurationSeconds());
			activeEvent.start(client);

			transitionTask = executor.schedule(
				() -> clientThread.invoke(this::finishEvent),
				activeEvent.getDurationSeconds(), TimeUnit.SECONDS);
		});
	}

	void stopTestEvent()
	{
		clientThread.invoke(this::forceFinishEvent);
	}

	private void startRandomEvent()
	{
		cancelTransition();
		if (!config.autoStart())
		{
			phase = Phase.WAITING;
			deadline = Instant.EPOCH;
			return;
		}
		if (activeEvent != null) activeEvent.stop(client);
		List<ChaosMod> pool = ChaosModFactory.createRandomPool(random, config);
		if (pool.isEmpty()) return;
		activeEvent = pool.get(random.nextInt(pool.size()));
		phase = Phase.ACTIVE; deadline = Instant.now().plusSeconds(activeEvent.getDurationSeconds()); activeEvent.start(client);
		transitionTask = executor.schedule(() -> clientThread.invoke(this::finishEvent), activeEvent.getDurationSeconds(), TimeUnit.SECONDS);
	}

	private void finishEvent()
	{
		finishEventInternal(false);
	}

	private void forceFinishEvent()
	{
		finishEventInternal(true);
	}

	private void finishEventInternal(boolean force)
	{
		cancelTransition();
		if (!force && activeEvent != null && !activeEvent.canStop())
		{
			transitionTask = executor.schedule(
				() -> clientThread.invoke(this::finishEvent), 100, TimeUnit.MILLISECONDS);
			return;
		}
		if (activeEvent != null) activeEvent.stop(client);
		activeEvent = null; phase = Phase.WAITING; deadline = Instant.EPOCH;
		if (config.autoStart()) scheduleNewRound(config.betweenRoundsSeconds());
	}

	private void scheduleNewRound(int seconds)
	{
		cancelTransition();
		int delay = Math.max(0, seconds);
		phase = Phase.WAITING;
		deadline = Instant.now().plusSeconds(delay);
		transitionTask = executor.schedule(this::startRound, delay, TimeUnit.SECONDS);
	}

	private void cancelTransition()
	{
		if (transitionTask != null) transitionTask.cancel(false);
		transitionTask = null;
	}

	private void updateSidebarPanel()
	{
		if (config.showSidebarPanel())
		{
			if (navigationButton == null)
			{
				navigationButton = NavigationButton.builder()
					.tooltip("Chaos Mod")
					.icon(createSidebarIcon())
					.priority(5)
					.panel(panel)
					.build();
				clientToolbar.addNavigation(navigationButton);
			}
			return;
		}

		removeSidebarPanel();
	}

	private void removeSidebarPanel()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
	}

	private static BufferedImage createSidebarIcon()
	{
		try (InputStream iconStream = ChaosModPlugin.class.getResourceAsStream("/chaos_mod_icon.png"))
		{
			BufferedImage icon = iconStream == null ? null : ImageIO.read(iconStream);
			if (icon != null)
			{
				return icon;
			}
		}
		catch (IOException exception)
		{
			log.warn("Unable to load Chaos Mod sidebar icon", exception);
		}

		return createFallbackSidebarIcon();
	}

	private static BufferedImage createFallbackSidebarIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(new Color(35, 155, 205));
			graphics.fillOval(1, 1, 14, 14);
			graphics.setColor(new Color(255, 190, 45));
			graphics.fill(new Polygon(
				new int[] {9, 5, 7, 4, 10, 8},
				new int[] {2, 8, 8, 14, 7, 7}, 6));
		}
		finally
		{
			graphics.dispose();
		}
		return icon;
	}

	@Provides
	ChaosModConfig provideConfig(ConfigManager manager) { return manager.getConfig(ChaosModConfig.class); }
}

package com.chaosmod;

import com.chaosmod.events.ChaosMod;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** Draws the event effects that intentionally need to appear over game widgets. */
final class ChaosModWidgetOverlay extends Overlay
{
	private final Client client;
	private final ChaosModPlugin plugin;

	@Inject
	ChaosModWidgetOverlay(Client client, ChaosModPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override public Dimension render(Graphics2D graphics)
	{
		ChaosMod activeEvent = plugin.getActiveEvent();
		if (activeEvent != null)
		{
			activeEvent.renderWidgets(client, graphics);
		}
		return null;
	}
}

package com.chaosmod.events;

import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptCallbackEvent;

public interface ChaosMod
{
	String getName();
	String getDescription();
	int getDurationSeconds();
	void start(Client client);
	void stop(Client client);

	default void onGameTick(Client client) { }
	default void onClientTick(Client client) { }
	default void onMenuOptionClicked(Client client, MenuOptionClicked event) { }
	default void onScriptCallbackEvent(Client client, ScriptCallbackEvent event) { }
	default void render(Client client, Graphics2D graphics) { }
	default void renderTileMarkers(Client client, Graphics2D graphics) { }
	default void renderWidgets(Client client, Graphics2D graphics) { }
	default boolean isComplete() { return false; }
	default boolean canStop() { return true; }
}

package com.chaosmod.events;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.function.Supplier;
import com.chaosmod.ChaosModConfig;

public final class ChaosModFactory
{
	private ChaosModFactory() { }

	public static List<ChaosMod> createAllEvents(Random random, ChaosModConfig config)
	{
		return createEvents(random, config, true);
	}

	public static List<ChaosMod> createRandomPool(Random random, ChaosModConfig config)
	{
		return createEvents(random, config, false);
	}

	private static List<ChaosMod> createEvents(Random random, ChaosModConfig config,
		boolean includeDisabledEvents)
	{
		List<ChaosMod> events = new ArrayList<>();
		add(events, includeDisabledEvents || config.includeBarrels(), () -> new ExplodingBarrelsEvent(duration(config, config.barrelsSeconds()), random));
		add(events, includeDisabledEvents || config.includeLightsOut(), () -> new LightsOutEvent(duration(config, config.lightsOutSeconds())));
		add(events, includeDisabledEvents || config.includeJad(), () -> new SpawnJadEvent(duration(config, config.jadSeconds()), random));
		add(events, includeDisabledEvents || config.includeMeteor(), () -> new YamaMeteorShowerEvent(duration(config, config.meteorSeconds())));
		add(events, includeDisabledEvents || config.includeNoobOutfit(), () -> new NoobOutfitEvent(duration(config, config.noobOutfitSeconds())));
		add(events, includeDisabledEvents || config.includeGuitarHero(), () -> new GuitarHeroEvent(duration(config, config.guitarHeroSeconds()), random));
		add(events, includeDisabledEvents || config.includeVardorvis(), () -> new VardorvisCaptchaEvent(duration(config, config.vardorvisSeconds()), random));
		add(events, includeDisabledEvents || config.includeDirtyScreen(), () -> new DirtyScreenEvent(duration(config, config.dirtyScreenSeconds()), random));
		add(events, includeDisabledEvents || config.includeCoxPortals(), () -> new CoxPortalsEvent(duration(config, config.coxPortalsSeconds()), random));
		return events;
	}

	private static void add(List<ChaosMod> events, boolean enabled, Supplier<ChaosMod> event)
	{
		if (enabled)
		{
			events.add(event.get());
		}
	}

	private static int duration(ChaosModConfig config, int overrideSeconds)
	{
		return overrideSeconds > 0 ? overrideSeconds : config.eventSeconds();
	}
}

package com.chaosmod.events;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;

@Getter
final class CoxPortalsEvent implements ChaosMod
{
    private static final int MAX_PORTAL_DISTANCE = 5;
    private static final int COUNTDOWN_TICKS = 5;
    private static final long PORTAL_DELAY_NANOS = 5_000_000_000L;
    private static final long INVENTORY_LOCK_NANOS = 10_000_000_000L;

    // Apparently the portal is a NPC.
    private static final int PORTAL_NPC_ID = 3086;
    private static final int PORTAL_ANIMATION = 504;
    private final String name = "CoX Portals";
    private final String description = "Reach Olm's portal before the 3-tick countdown ends";
    private final int durationSeconds;
    private final Random random;

    private LocalPoint portalLocation;
    private int portalEndTick = -1;
    private long nextPortalNanos;
    private long inventoryLockedUntilNanos;
    private RuneLiteObject portalObject;

    CoxPortalsEvent(int durationSeconds, Random random)
    {
        this.durationSeconds = durationSeconds;
        this.random = random;
    }

    @Override
    public void start(Client client)
    {
        stop(client);
        nextPortalNanos = System.nanoTime();
    }

    @Override
    public void onClientTick(Client client)
    {
        if (portalLocation != null)
        {
            updatePortalVisual(client);
            return;
        }

        if (isInventoryLocked())
        {
            return;
        }

        if (System.nanoTime() >= nextPortalNanos)
        {
            spawnPortal(client);
        }
    }

    @Override
    public void onGameTick(Client client)
    {
        if (portalLocation == null)
        {
            return;
        }

        int tick = client.getTickCount();
        if (tick < portalEndTick)
        {
            return;
        }

        Player player = client.getLocalPlayer();
        boolean success = player != null
                && player.getLocalLocation() != null
                && isSameTile(player.getLocalLocation(), portalLocation);

        destroyPortalVisual();
        portalLocation = null;
        portalEndTick = -1;

        if (!success)
        {
            inventoryLockedUntilNanos = System.nanoTime() + INVENTORY_LOCK_NANOS;
            nextPortalNanos = inventoryLockedUntilNanos + PORTAL_DELAY_NANOS;
        }
        else
        {
            nextPortalNanos = System.nanoTime() + PORTAL_DELAY_NANOS;
        }
    }

    @Override
    public void onMenuOptionClicked(Client client, MenuOptionClicked event)
    {
		if (isInventoryLocked() && EventInputUtil.isInventoryClick(event))
        {
            event.consume();
        }
    }

    @Override
    public boolean canStop()
    {
        return !isInventoryLocked();
    }

    @Override
    public void render(Client client, Graphics2D graphics)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            if (portalLocation != null)
            {
                drawPortal(client, g);
            }

            if (isInventoryLocked())
            {
                long remainingMillis = Math.max(0L,
                        (inventoryLockedUntilNanos - System.nanoTime()) / 1_000_000L);
                EventOverlayUtil.drawCentered(client, g,
                        String.format("INVENTORY LOCKED: %.1fs", remainingMillis / 1000.0),
                        200, Color.RED, 20f);
            }
        }
        finally
        {
            g.dispose();
        }
    }

    @Override
    public void stop(Client client)
    {
        destroyPortalVisual();
        portalLocation = null;
        portalEndTick = -1;
        nextPortalNanos = 0L;
        inventoryLockedUntilNanos = 0L;
    }

    private void spawnPortal(Client client)
    {
        Player player = client.getLocalPlayer();
        if (player == null || player.getWorldLocation() == null)
        {
            nextPortalNanos = System.nanoTime() + 100_000_000L;
            return;
        }

        WorldPoint target = findReachablePortalTile(client, player.getWorldLocation());
        if (target == null)
        {
            nextPortalNanos = System.nanoTime() + 250_000_000L;
            return;
        }

        LocalPoint local = LocalPoint.fromWorld(client, target);
        if (local == null)
        {
            nextPortalNanos = System.nanoTime() + 250_000_000L;
            return;
        }

        portalLocation = EventTileUtil.snapToTileCenter(local);
        portalEndTick = client.getTickCount() + COUNTDOWN_TICKS;
        updatePortalVisual(client);
    }


    // actually find reachable tiles for the player
    private WorldPoint findReachablePortalTile(Client client, WorldPoint start)
    {
        for (int attempt = 0; attempt < 24; attempt++)
        {
            WorldPoint current = start;
            int steps = 1 + random.nextInt(MAX_PORTAL_DISTANCE);

            for (int step = 0; step < steps; step++)
            {
                List<int[]> directions = new ArrayList<>();
                directions.add(new int[] { 1, 0 });
                directions.add(new int[] { -1, 0 });
                directions.add(new int[] { 0, 1 });
                directions.add(new int[] { 0, -1 });
                directions.add(new int[] { 1, 1 });
                directions.add(new int[] { 1, -1 });
                directions.add(new int[] { -1, 1 });
                directions.add(new int[] { -1, -1 });
                Collections.shuffle(directions, random);

                boolean moved = false;
                for (int[] direction : directions)
                {
                    WorldArea area = new WorldArea(current, 1, 1);
                    if (!area.canTravelInDirection(
                            client.getTopLevelWorldView(),
                            direction[0],
                            direction[1]))
                    {
                        continue;
                    }

                    WorldPoint next = new WorldPoint(
                            current.getX() + direction[0],
                            current.getY() + direction[1],
                            current.getPlane());

                    if (start.distanceTo2D(next) > MAX_PORTAL_DISTANCE)
                    {
                        continue;
                    }

                    current = next;
                    moved = true;
                    break;
                }

                if (!moved)
                {
                    break;
                }
            }

            if (!current.equals(start) && start.distanceTo2D(current) <= MAX_PORTAL_DISTANCE)
            {
                return current;
            }
        }

        return null;
    }

    private void drawPortal(Client client, Graphics2D g)
    {
        if (portalLocation == null)
        {
            return;
        }

        Point point = Perspective.localToCanvas(
                client, portalLocation, client.getPlane());
        if (point == null)
        {
            return;
        }

        int ticksLeft = Math.max(0, portalEndTick - client.getTickCount());
        String countdown = Integer.toString(ticksLeft);
        g.setFont(g.getFont().deriveFont(Font.BOLD, 22f));
        int textWidth = g.getFontMetrics().stringWidth(countdown);
        int x = point.getX() - textWidth / 2;
        int y = point.getY() - 28;
        g.setColor(Color.BLACK);
        g.drawString(countdown, x + 2, y + 2);
        g.setColor(Color.WHITE);
        g.drawString(countdown, x, y);
    }

    private Model buildPortalModel(Client client)
    {
        NPCComposition composition = client.getNpcDefinition(PORTAL_NPC_ID);
        if (composition == null)
        {
            return null;
        }

        int[] modelIds = composition.getModels();
        if (modelIds == null || modelIds.length == 0)
        {
            return null;
        }

        ModelData[] parts = new ModelData[modelIds.length];
        for (int i = 0; i < modelIds.length; i++)
        {
            parts[i] = client.loadModelData(modelIds[i]);
            if (parts[i] == null)
            {
                return null;
            }
        }

        ModelData modelData = parts.length == 1 ? parts[0] : client.mergeModels(parts);
        if (modelData == null)
        {
            return null;
        }

        short[] find = composition.getColorToReplace();
        short[] replace = composition.getColorToReplaceWith();
        if (find != null && replace != null)
        {
            modelData = modelData.cloneColors();
            int count = Math.min(find.length, replace.length);
            for (int i = 0; i < count; i++)
            {
                modelData.recolor(find[i], replace[i]);
            }
        }

        int widthScale = composition.getWidthScale();
        int heightScale = composition.getHeightScale();
        if (widthScale != 128 || heightScale != 128)
        {
            modelData = modelData.cloneVertices();
            modelData.scale(widthScale, heightScale, widthScale);
        }

        return modelData.light(ModelData.DEFAULT_AMBIENT, ModelData.DEFAULT_CONTRAST,
                ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
    }

    private void updatePortalVisual(Client client)
    {
        if (portalLocation == null)
        {
            destroyPortalVisual();
            return;
        }

        if (portalObject == null)
        {
            Model model = buildPortalModel(client);
            if (model == null)
            {
                return;
            }

            portalObject = client.createRuneLiteObject();
            portalObject.setModel(model);
            portalObject.setLocation(portalLocation, client.getPlane());
            portalObject.setDrawFrontTilesFirst(true);
			Animation animation = client.loadAnimation(PORTAL_ANIMATION);
            if (animation != null)
            {
                AnimationController controller = new AnimationController(client, animation);
                controller.setOnFinished(AnimationController::loop);
                portalObject.setAnimationController(controller);
            }

            portalObject.setActive(true);
            return;
        }

        portalObject.setLocation(portalLocation, client.getPlane());
    }

    private void destroyPortalVisual()
    {
        if (portalObject != null)
        {
            portalObject.setActive(false);
            portalObject.setModel(null);
            portalObject = null;
        }
    }

    private boolean isInventoryLocked()
    {
        return System.nanoTime() < inventoryLockedUntilNanos;
    }

    private static boolean isSameTile(LocalPoint a, LocalPoint b)
    {
        return a != null && b != null
                && a.getSceneX() == b.getSceneX()
                && a.getSceneY() == b.getSceneY();
    }

}

package com.chaosmod.events;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Random;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Point;

@Getter
final class DirtyScreenEvent implements ChaosMod
{
	private static final int CLEAN_RADIUS = 4;
	private static final int MUD_BLOTCH_COUNT = 260;

	private final String name = "Dirty Screen";
	private final String description = "Clean the mud by moving your mouse over the screen";
	private final int durationSeconds;
	private final Random random;

	private BufferedImage mud;
	private Point lastMouse;
	private int canvasWidth;
	private int canvasHeight;

	DirtyScreenEvent(int durationSeconds, Random random)
	{
		this.durationSeconds = durationSeconds;
		this.random = random;
	}

	@Override
	public synchronized void start(Client client)
	{
		stop(client);
		createMud(client.getCanvasWidth(), client.getCanvasHeight());
	}

	@Override
	public synchronized void onClientTick(Client client)
	{
		int width = client.getCanvasWidth();
		int height = client.getCanvasHeight();
		if (mud == null || width != canvasWidth || height != canvasHeight)
		{
			createMud(width, height);
			if (mud == null)
			{
				return;
			}
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0
			|| mouse.getX() >= canvasWidth || mouse.getY() >= canvasHeight)
		{
			lastMouse = null;
			return;
		}

		Graphics2D g = mud.createGraphics();
		try
		{
			g.setComposite(AlphaComposite.Clear);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(new BasicStroke(CLEAN_RADIUS * 2f, BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			if (lastMouse == null)
			{
				g.fillOval(mouse.getX() - CLEAN_RADIUS, mouse.getY() - CLEAN_RADIUS,
					CLEAN_RADIUS * 2, CLEAN_RADIUS * 2);
			}
			else
			{
				g.drawLine(lastMouse.getX(), lastMouse.getY(), mouse.getX(), mouse.getY());
			}
		}
		finally
		{
			g.dispose();
		}
		lastMouse = mouse;
	}

	@Override
	public synchronized void renderWidgets(Client client, Graphics2D graphics)
	{
		if (mud != null)
		{
			graphics.drawImage(mud, 0, 0, null);
		}
	}

	@Override
	public synchronized void stop(Client client)
	{
		mud = null;
		lastMouse = null;
		canvasWidth = 0;
		canvasHeight = 0;
	}

	private void createMud(int width, int height)
	{
		if (width <= 0 || height <= 0)
		{
			mud = null;
			lastMouse = null;
			return;
		}

		canvasWidth = width;
		canvasHeight = height;
		lastMouse = null;
		mud = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = mud.createGraphics();
		try
		{
			g.setColor(new Color(70, 43, 20, 252));
			g.fillRect(0, 0, width, height);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			Color[] colors =
			{
				new Color(45, 28, 13, 235),
				new Color(88, 55, 25, 245),
				new Color(112, 73, 32, 225),
				new Color(58, 37, 17, 240)
			};
			for (int i = 0; i < MUD_BLOTCH_COUNT; i++)
			{
				int blotchWidth = 24 + random.nextInt(100);
				int blotchHeight = 16 + random.nextInt(70);
				int x = random.nextInt(width + blotchWidth) - blotchWidth;
				int y = random.nextInt(height + blotchHeight) - blotchHeight;
				g.setColor(colors[random.nextInt(colors.length)]);
				g.fillOval(x, y, blotchWidth, blotchHeight);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.chaosmod.events;

import java.util.Locale;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;

final class EventInputUtil
{
	private EventInputUtil() { }

	static boolean isWalkClick(MenuOptionClicked event)
	{
		return event.getMenuAction() == MenuAction.WALK;
	}

	static boolean isPrayerActivationClick(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null || !"activate".equals(option.toLowerCase(Locale.ROOT)))
		{
			return false;
		}
		Widget widget = event.getWidget();
		if (widget != null && (widget.getId() >>> 16) == InterfaceID.PRAYERBOOK)
		{
			return true;
		}
		String target = event.getMenuTarget();
		return target != null && target.toLowerCase(Locale.ROOT).contains("prayer");
	}

	static boolean isInventoryClick(MenuOptionClicked event)
	{
		Widget widget = event.getWidget();
		if (widget != null && (widget.getId() >>> 16) == InterfaceID.INVENTORY)
		{
			return true;
		}
		return event.getMenuAction() == MenuAction.WIDGET_TARGET
			&& (event.getParam1() >>> 16) == InterfaceID.INVENTORY;
	}

	// whatever the player can interact on the world map should be blocked here
	static boolean isWorldInteractionClick(MenuAction action)
	{
		switch (action)
		{
			case WALK: case GAME_OBJECT_FIRST_OPTION: case GAME_OBJECT_SECOND_OPTION: case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION: case GAME_OBJECT_FIFTH_OPTION: case NPC_FIRST_OPTION: case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION: case NPC_FOURTH_OPTION: case NPC_FIFTH_OPTION: case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION: case PLAYER_THIRD_OPTION: case PLAYER_FOURTH_OPTION: case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION: case PLAYER_SEVENTH_OPTION: case PLAYER_EIGHTH_OPTION: case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION: case GROUND_ITEM_THIRD_OPTION: case GROUND_ITEM_FOURTH_OPTION: case GROUND_ITEM_FIFTH_OPTION:
			case WIDGET_TARGET_ON_GAME_OBJECT: case WIDGET_TARGET_ON_NPC: case WIDGET_TARGET_ON_PLAYER:
			case WIDGET_TARGET_ON_GROUND_ITEM: case WORLD_ENTITY_FIRST_OPTION: case WORLD_ENTITY_SECOND_OPTION:
			case WORLD_ENTITY_THIRD_OPTION: case WORLD_ENTITY_FOURTH_OPTION: case WORLD_ENTITY_FIFTH_OPTION:
			case EXAMINE_OBJECT: case EXAMINE_NPC: case EXAMINE_ITEM_GROUND: case EXAMINE_WORLD_ENTITY:
				return true;
			default:
				return false;
		}
	}
}

package com.chaosmod.events;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import net.runelite.api.Client;

final class EventOverlayUtil
{
	private EventOverlayUtil()
	{
	}

	static void drawCentered(Client client, Graphics2D graphics, String text, int y,
		Color color, float fontSize)
	{
		graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, fontSize));
		int x = (client.getCanvasWidth() - graphics.getFontMetrics().stringWidth(text)) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 2, y + 2);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

package com.chaosmod.events;

import net.runelite.api.coords.LocalPoint;

final class EventTileUtil
{
	private static final int TILE_SIZE = 128;
	private static final int TILE_CENTER_OFFSET = TILE_SIZE / 2;

	private EventTileUtil() { }

	static LocalPoint snapToTileCenter(LocalPoint point)
	{
		if (point == null)
		{
			return null;
		}

		int centeredX = (point.getX() / TILE_SIZE) * TILE_SIZE + TILE_CENTER_OFFSET;
		int centeredY = (point.getY() / TILE_SIZE) * TILE_SIZE + TILE_CENTER_OFFSET;
		return new LocalPoint(centeredX, centeredY, point.getWorldView());
	}
}

package com.chaosmod.events;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Random;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
